     2→
     3→use super::{
     4→    dao_fork, eip6110,
     5→    receipt_builder::{AlloyReceiptBuilder, ReceiptBuilder, ReceiptBuilderCtx},
     6→    spec::{EthExecutorSpec, EthSpec},
     7→    EthEvmFactory,
     8→};
     9→use crate::{
    10→    block::{
    11→        state_changes::{balance_increment_state, post_block_balance_increments},
    12→        BlockExecutionError, BlockExecutionResult, BlockExecutor, BlockExecutorFactory,
    13→        BlockExecutorFor, BlockValidationError, ExecutableTx, OnStateHook,
    14→        StateChangePostBlockSource, StateChangeSource, SystemCaller,
    15→    },
    16→    Database, Evm, EvmFactory, FromRecoveredTx, FromTxWithEncoded,
    17→};
    18→use alloc::{borrow::Cow, boxed::Box, vec::Vec};
    19→use alloy_consensus::{Header, Transaction, TxReceipt};
    20→use alloy_eips::{eip4895::Withdrawals, eip7685::Requests, Encodable2718};
    21→use alloy_hardforks::EthereumHardfork;
    22→use alloy_primitives::{Log, B256};
    23→use revm::{context_interface::result::ResultAndState, database::State, DatabaseCommit, Inspector};
    24→
    25→/// Context for Ethereum block execution.
    26→#[derive(Debug, Clone)]
    27→pub struct EthBlockExecutionCtx<'a> {
    28→    /// Parent block hash.
    29→    pub parent_hash: B256,
    30→    /// Parent beacon block root.
    31→    pub parent_beacon_block_root: Option<B256>,
    32→    /// Block ommers
    33→    pub ommers: &'a [Header],
    34→    /// Block withdrawals.
    35→    pub withdrawals: Option<Cow<'a, Withdrawals>>,
    36→}
    37→
    38→/// Block executor for Ethereum.
    39→#[derive(Debug)]
    40→pub struct EthBlockExecutor<'a, Evm, Spec, R: ReceiptBuilder> {
    41→    /// Reference to the specification object.
    42→    spec: Spec,
    43→
    44→    /// Context for block execution.
    45→    pub ctx: EthBlockExecutionCtx<'a>,
    46→    /// Inner EVM.
    47→    evm: Evm,
    48→    /// Utility to call system smart contracts.
    49→    system_caller: SystemCaller<Spec>,
    50→    /// Receipt builder.
    51→    receipt_builder: R,
    52→
    53→    /// Receipts of executed transactions.
    54→    receipts: Vec<R::Receipt>,
    55→    /// Total gas used by transactions in this block.
    56→    gas_used: u64,
    57→}
    58→
    59→impl<'a, Evm, Spec, R> EthBlockExecutor<'a, Evm, Spec, R>
    60→where
    61→    Spec: Clone,
    62→    R: ReceiptBuilder,
    63→{
    64→    /// Creates a new [`EthBlockExecutor`]
    65→    pub fn new(evm: Evm, ctx: EthBlockExecutionCtx<'a>, spec: Spec, receipt_builder: R) -> Self {
    66→        Self {
    67→            evm,
    68→            ctx,
    69→            receipts: Vec::new(),
    70→            gas_used: 0,
    71→            system_caller: SystemCaller::new(spec.clone()),
    72→            spec,
    73→            receipt_builder,
    74→        }
    75→    }
    76→}
    77→
    78→impl<'db, DB, E, Spec, R> BlockExecutor for EthBlockExecutor<'_, E, Spec, R>
    79→where
    80→    DB: Database + 'db,
    81→    E: Evm<
    82→        DB = &'db mut State<DB>,
    83→        Tx: FromRecoveredTx<R::Transaction> + FromTxWithEncoded<R::Transaction>,
    84→    >,
    85→    Spec: EthExecutorSpec,
    86→    R: ReceiptBuilder<Transaction: Transaction + Encodable2718, Receipt: TxReceipt<Log = Log>>,
    87→{
    88→    type Transaction = R::Transaction;
    89→    type Receipt = R::Receipt;
    90→    type Evm = E;
    91→
    92→    fn apply_pre_execution_changes(&mut self) -> Result<(), BlockExecutionError> {
    93→        // Set state clear flag if the block is after the Spurious Dragon hardfork.
    94→        let state_clear_flag =
    95→            self.spec.is_spurious_dragon_active_at_block(self.evm.block().number.saturating_to());
    96→        self.evm.db_mut().set_state_clear_flag(state_clear_flag);
    97→
    98→        self.system_caller.apply_blockhashes_contract_call(self.ctx.parent_hash, &mut self.evm)?;
    99→        self.system_caller
   100→            .apply_beacon_root_contract_call(self.ctx.parent_beacon_block_root, &mut self.evm)?;
   101→
   102→        Ok(())
   103→    }
   104→
   105→    fn execute_transaction_without_commit(
   106→        &mut self,
   107→        tx: impl ExecutableTx<Self>,
   108→    ) -> Result<ResultAndState<<Self::Evm as Evm>::HaltReason>, BlockExecutionError> {
   109→        // The sum of the transaction's gas limit, Tg, and the gas utilized in this block prior,
   110→        // must be no greater than the block's gasLimit.
   111→        let block_available_gas = self.evm.block().gas_limit - self.gas_used;
   112→
   113→        if tx.tx().gas_limit() > block_available_gas {
   114→            return Err(BlockValidationError::TransactionGasLimitMoreThanAvailableBlockGas {
   115→                transaction_gas_limit: tx.tx().gas_limit(),
   116→                block_available_gas,
   117→            }
   118→            .into());
   119→        }
   120→
   121→        // Execute transaction and return the result
   122→        self.evm.transact(&tx).map_err(|err| {
   123→            let hash = tx.tx().trie_hash();
   124→            BlockExecutionError::evm(err, hash)
   125→        })
   126→    }
   127→
   128→    fn commit_transaction(
   129→        &mut self,
   130→        output: ResultAndState<<Self::Evm as Evm>::HaltReason>,
   131→        tx: impl ExecutableTx<Self>,
   132→    ) -> Result<u64, BlockExecutionError> {
   133→        let ResultAndState { result, state } = output;
   134→
   135→        self.system_caller.on_state(StateChangeSource::Transaction(self.receipts.len()), &state);
   136→
   137→        let gas_used = result.gas_used();
   138→
   139→        // append gas used
   140→        self.gas_used += gas_used;
